#!/usr/bin/env bash
set -euo pipefail

# Strengthens Home's alternating section backgrounds from blush-50 to
# blush-100 so the pink-surface direction actually reads as intentional
# instead of blending into white.
#
# Clones into an isolated, branch-named directory ("gowebsite-claude-home-blush-strengthen") right next
# to wherever you run this, so it never collides with your Codespace's own
# repo checkout or with leftovers from previous apply_*.sh runs.

REPO_URL="https://github.com/yoosuf0806/go-website.git"
BRANCH="claude/home-blush-strengthen"
DIR="gowebsite-claude-home-blush-strengthen"

if [ -d "$DIR" ]; then
  echo "$DIR already exists here (probably from a previous run of this exact script) — remove it first:" >&2
  echo "  rm -rf $DIR" >&2
  exit 1
fi

echo "Cloning fresh main into $DIR..."
git clone "$REPO_URL" "$DIR"
cd "$DIR"
git checkout -b "$BRANCH"

echo "Applying patch..."
base64 -d <<'PATCH_B64' | git am

PATCH_B64

echo
echo "Patch applied cleanly on branch $BRANCH in ./$DIR"
echo "Next steps:"
echo "  cd $DIR"
echo "  git push -u origin $BRANCH"
echo "  Open a PR: https://github.com/yoosuf0806/go-website/compare/main...$BRANCH"
